let sharedRefreshBusy=false;setInterval(async()=>{const d=$("dialog-content").firstElementChild;if(!auth||!sharedPresence||!d?.sharedRefresh||d.contains(document.activeElement)||sharedRefreshBusy||document.hidden)return;sharedRefreshBusy=true;try{await d.sharedRefresh()}catch{}finally{sharedRefreshBusy=false}},12000);
setInterval(checkNotifications,30000);
async function boot(){const config=await fetch("/config.json",{cache:"no-store"}).then(r=>r.json());if(!config.googleClientId)throw Error("Configurare WEB_GOOGLE_CLIENT_ID su Coolify.");for(let i=0;i<100&&!window.google?.accounts?.id;i++)await new Promise(r=>setTimeout(r,100));if(!window.google?.accounts?.id)throw Error("Google Sign-In non disponibile.");window.google.accounts.id.initialize({client_id:config.googleClientId,callback:r=>signIn(r.credential)});window.google.accounts.id.renderButton($("google"),{theme:"outline",size:"large",text:"signin_with",locale:"it"})}boot().catch(e=>$("login-error").textContent=e.message);
